    a = float(assign['step_deg_value'])
    b = float(assign['offset_b_value'])
    d = float(assign['delta_d_value'])
    p = int(assign['p'])
    q = int(assign['q'])
    # Domain checks
    if not isinstance(N, int) or N <= 0:
        return (False, None)
    # Ensure a matches 180/(N+1)
    if abs(a - 180.0 / (N + 1)) > 1e-12:
        # step does not match the intended structure
        return (False, None)
    if q <= 0 or gcd(p, q) != 1:
        return (False, None)
    # Final target angle: theta = (N+1)*a/2 + b = 90 + b (since a = 180/(N+1))
    theta_num = 90 * q - p
    theta_den = q
    if theta_num <= 0:
        return (False, None)
    g = gcd(theta_num, theta_den)
    m = theta_num // g
    n = theta_den // g
    theta = m / n
    if not (theta < 90 and theta > 0):
        return (False, None)
    # Compute S/T numerically to confirm correctness and nontriviality
    def deg2rad(x):
        return math.pi * x / 180.0
    # Common amplitude factor
    denom = math.sin(deg2rad(a / 2.0))
    if abs(denom) < 1e-15:
        return (False, None)
    amp = math.sin(deg2rad(N * a / 2.0)) / denom
    # Sum over offsets b-d, b, b+d
    angles = [((N + 1) * a / 2.0) + (b - d), ((N + 1) * a / 2.0) + b, ((N + 1) * a / 2.0) + (b + d)]
    S = sum(amp * math.sin(deg2rad(t)) for t in angles)
    T = sum(amp * math.cos(deg2rad(t)) for t in angles)
    if abs(T) < 1e-15:
        return (False, None)
    R = S / T
    target = math.tan(deg2rad((N + 1) * a / 2.0 + b))
    if not math.isfinite(R) or not math.isfinite(target):
        return (False, None)
    if abs(R - target) > 1e-9:
        # Numerical check failed: the ratio isn't matching tan(theta)
        return (False, None)
    # Additional difficulty checks
    if N < 24 or q < 11:
        return (False, None)
    ans = m + n
    if not (200 <= ans <= 2000):
        return (False, None)
    # Avoid common special angles
    if int(theta) in {15, 30, 36, 45, 60, 75}:
        return (False, None)
    return (True, ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
